def get_piece_color(sprite: Sprite) -> int:
    """"""
    color_val = sprite.pixels[(sprite.pixels != CENTER_MARKER) & (sprite.pixels != -1)][0]
    return int(color_val)


def get_center_color(sprite: Sprite) -> int:
    """"""
    cy = sprite.height // 2
    cx = sprite.width // 2
    return int(sprite.pixels[cy, cx])


def get_center_pos(sprite: Sprite) -> tuple[int, int]:
    """"""
    center_x = sprite.x + sprite.width // 2
    center_y = sprite.y + sprite.height // 2
    return (center_x, center_y)


def is_active_piece(sprite: Sprite) -> bool:
    """"""
    return get_center_color(sprite) == CENTER_MARKER


def crossed_boundary(di: int, dj: int, threshold: int) -> bool:
    """"""
    return di <= threshold and dj > threshold


def piece_matches_target(target_spr: Sprite, sprite: Sprite) -> bool:
    """

    """
    target_fill_color = target_spr.pixels[target_spr.pixels != -1][0]
    piece_color = get_piece_color(sprite)
    if piece_color == target_fill_color:
        dx = target_spr.x - sprite.x
        dy = target_spr.y - sprite.y
        colored_coords = np.argwhere(target_spr.pixels == target_fill_color)
        for i, j in colored_coords.tolist():
            if sprite.pixels[dy + i, dx + j] == -1:
                return False
        return True
    return False


class ColorTransitionAnimation:
    """



    """

    piece: Sprite
    target_cell: Sprite
    new_color: int

    def __init__(self, sprite: Sprite, target_cell_spr: Sprite, new_color: int) -> None:
        """"""
        self.piece = sprite
        self.target_cell = target_cell_spr
        self.new_color = new_color

    def next_frame(self) -> bool:
        """"""
        self.piece.set_rotation(self.target_cell.rotation)
        half = self.piece.width // 2
        if self.new_color != self.target_cell.pixels[1, 1]:
            self.piece.set_rotation(self.target_cell.rotation + 180)
        for i in range(0, half):
            if self.piece.pixels[i, half] != self.new_color:
                self.piece.pixels[i, half] = self.new_color
                return False
        for i in range(0, half):
            if self.piece.pixels[half, i + half + 1] != self.new_color:
                self.piece.pixels[half, i + half + 1] = self.new_color
                self.piece.pixels[half, half - i - 1] = self.new_color
                self.piece.pixels[i + half + 1, half] = self.new_color
                return False
        self.piece.set_rotation(0)
        return True


class StepCounterDisplay(RenderableUserDisplay):
    """


    """

    def __init__(self, max_steps: int):
        """"""
        self.max_steps = max_steps
        self.current_steps = max_steps

    def set_steps(self, steps: int) -> None:
        """"""
        self.current_steps = max(0, min(steps, self.max_steps))

    def decrement(self) -> bool:
        """"""
        if self.current_steps > 0:
            self.current_steps -= 1
        return self.current_steps > 0

    def reset(self) -> None:
        """"""
        self.current_steps = self.max_steps

    def render_interface(self, frame: np.ndarray) -> np.ndarray:
        """"""
        if self.max_steps == 0:
            return frame
        ratio = self.current_steps / self.max_steps
        filled_width = round(64 * ratio)
        bar_color = 15
        empty_color = 1
        for x in range(64):
            if x < filled_width:
                frame[63, x] = bar_color
            else:
                frame[63, x] = empty_color
        return frame




def _pixel_list_to_mask(pixels: list) -> list:
    """"""
    if pixels and isinstance(pixels[0], list):
        return [[0 if v == -1 else 1 for v in row] for row in pixels]
    return [0 if v == -1 else 1 for v in pixels]


def _build_sprite_knowledge(spr: Sprite) -> dict:
    """"""
    pix = spr.pixels.tolist()
    tags = list(spr._tags) if spr._tags else []
    return {
        "pixels":      pix,
        "mask_pixels": _pixel_list_to_mask(pix),
        "width":       int(spr.width),
        "height":      int(spr.height),
        "tags":        tags,
        "layer":       int(getattr(spr, "_layer", 0)),
    }


