class Re86(ARCBaseGame):
    """













    """

    step_counter: StepCounterDisplay
    active_target: Sprite | None
    active_piece: Sprite | None

    def __init__(self) -> None:
        self.step_counter = StepCounterDisplay(0)







        self._log_state = ActionLogState(aggregator=default_aggregator, post_process=self._compose_summary)


        self.touched_color_targets: set[str] = set()


        self._frame_sprite_log:     list[list[dict]] = []
        self._frame_nonsprite_log:  list[list[dict]] = []

        camera = Camera(
            background=BACKGROUND_COLOR,
            letter_box=PADDING_COLOR,
            interfaces=[self.step_counter],
        )
        super().__init__(
            game_id="re86",
            levels=levels,
            camera=camera,
            available_actions=[1, 2, 3, 4, 5],
        )

    def _get_hidden_state(self) -> np.ndarray:
        """"""
        hidden_state = np.zeros((1, 1), dtype=np.int16)
        hidden_state[0] = self.step_counter.current_steps
        return hidden_state

    def on_set_level(self, level: Level) -> None:
        """"""
        self._init_step_counter()
        self.active_target = None
        self.active_piece = None




        self.active_from_color: int | None = None
        self.touched_color_targets = set()

    def _init_step_counter(self) -> None:
        """"""
        max_steps_val = self.current_level.get_data("StepCounter")
        self.step_counter.max_steps = max_steps_val
        self.step_counter.reset()

    def _check_win(self) -> bool:
        """"""
        target_patterns = self.current_level.get_sprites_by_tag("target_pattern")
        pieces = self.current_level.get_sprites_by_tag("piece")
        canvas_pixels = sprites["canvas_64x64"].pixels.copy()
        canvas_height, canvas_width = canvas_pixels.shape
        for sprite in pieces:
            piece_w = sprite.width
            piece_h = sprite.height
            src_row_start = max(0, -sprite.y)
            src_row_end = min(piece_h, canvas_height - sprite.y)
            src_col_start = max(0, -sprite.x)
            src_col_end = min(piece_w, canvas_width - sprite.x)
            dst_row_start = max(0, sprite.y)
            dst_row_end = min(64, sprite.y + piece_h)
            dst_col_start = max(0, sprite.x)
            dst_col_end = min(64, sprite.x + piece_w)
            if src_row_end > src_row_start and src_col_end > src_col_start:
                src_slice = sprite.pixels[src_row_start:src_row_end, src_col_start:src_col_end]
                dst_slice = canvas_pixels[dst_row_start:dst_row_end, dst_col_start:dst_col_end]
                visible_mask = src_slice != -1
                dst_slice[visible_mask] = src_slice[visible_mask]
        for target_spr in target_patterns:
            if np.any((target_spr.pixels != -1) & (target_spr.pixels != 4) & (target_spr.pixels != canvas_pixels)):
                return False
        return True

    def _deselect_all_pieces(self) -> None:
        """"""
        pieces = self.current_level.get_sprites_by_tag("piece")
        for sprite in pieces:
            cy = sprite.height // 2
            cx = sprite.width // 2
            if "hollow_piece" in sprite.tags:
                sprite.pixels[cy, cx] = -1
            else:
                piece_color = get_piece_color(sprite)
                if "cross_piece" in sprite.tags:
                    sprite.pixels[cy, cx] = piece_color
                else:
                    for solid_col in range(sprite.width):
                        if np.all(sprite.pixels[:, solid_col] != -1):
                            break
                    for solid_row in range(sprite.height):
                        if np.all(sprite.pixels[solid_row, :] != -1):
                            break
                    if cy == solid_row or cx == solid_col:
                        sprite.pixels[cy, cx] = piece_color
                    else:
                        sprite.pixels[cy, cx] = -1

    def _is_on_screen(self, sprite: Sprite) -> bool:
        """"""
        x, y = get_center_pos(sprite)
        return x >= 0 and y >= 0 and (x < self.camera.width) and (y < self.camera.height)

    def _try_move_piece(self, sprite: Sprite, dx: int, dy: int) -> Sprite | None:
        """



        """
        sprite.move(dx, dy)
        if not self._is_on_screen(sprite):
            sprite.move(-dx, -dy)
            return None
        min_size = 6
        walls = self.current_level.get_sprites_by_tag("wall")
        for wall_spr in walls:
            if sprite.collides_with(wall_spr):
                if "hollow_piece" in sprite.tags:


                    def _emit_hollow_log(before_orient: str, after_orient: str, stretches: str, l2_stretches: str) -> None:
                        _dx, _dy, _dw, _dh = self._to_display_bbox(sprite)
                        self.action_log.append(
                            f"[change]:[{sprite.name}]:[sname({sprite.name});shape({before_orient})_({after_orient});position({_dx}_{_dy});bbox({_dw}_{_dh})]:{sprite.name} hits the wall and stretches {stretches}.|The Object hits the wall and stretches {stretches}."
                        )
                        self.action_log_l2.append(
                            f"[change]:[{sprite.name}]:[sname({sprite.name});shape({before_orient})_({after_orient});position({_dx}_{_dy});bbox({_dw}_{_dh})]:{sprite.name}{l2_stretches}|Object{l2_stretches}"
                        )

                    if dx < 0 or dx > 0:
                        if sprite.width > min_size:
                            cy = sprite.height // 2
                            cx = sprite.width // 2
                            sprite.pixels[cy, cx] = -1
                            piece_color = get_piece_color(sprite)
                            height, width = sprite.pixels.shape
                            y_offset = height // 2 - (height + 3) // 2
                            sprite.pixels = np.zeros((height + 3, width - 3))
                            sprite.pixels[:] = -1
                            sprite.pixels[:, -1] = piece_color
                            sprite.pixels[:, 0] = piece_color
                            sprite.pixels[0, :] = piece_color
                            sprite.pixels[-1, :] = piece_color
                            cy = sprite.height // 2
                            cx = sprite.width // 2
                            sprite.pixels[cy, cx] = CENTER_MARKER
                            sprite.move(0, y_offset)
                            sprite.move(0, round(sprite.y / 3) * 3 - sprite.y)


                            _emit_hollow_log("horizontal", "vertical", "vertically", "")
                            if dx < 0:
                                sprite.move(-dx, -dy)
                        else:
                            _emit_hollow_log("horizontal", "vertical", "vertically", "")
                            sprite.move(-dx, -dy)
                    elif dy < 0 or dy > 0:
                        if sprite.height > min_size:
                            cy = sprite.height // 2
                            cx = sprite.width // 2
                            sprite.pixels[cy, cx] = -1
                            piece_color = get_piece_color(sprite)
                            height, width = sprite.pixels.shape
                            x_offset = width // 2 - (width + 3) // 2
                            sprite.pixels = np.zeros((height - 3, width + 3))
                            sprite.pixels[:] = -1
                            sprite.pixels[:, -1] = piece_color
                            sprite.pixels[:, 0] = piece_color
                            sprite.pixels[0, :] = piece_color
                            sprite.pixels[-1, :] = piece_color
                            cy = sprite.height // 2
                            cx = sprite.width // 2
                            sprite.pixels[cy, cx] = CENTER_MARKER
                            sprite.move(x_offset, 0)
                            sprite.move(round(sprite.x / 3) * 3 - sprite.x, 0)


                            _emit_hollow_log("vertical", "horizontal", "horizontally", "")
                            if dy < 0:
                                sprite.move(-dx, -dy)
                        else:
                            _emit_hollow_log("vertical", "horizontal", "horizontally", "")
                            sprite.move(-dx, -dy)
                    return None
                else:
                    piece_color = get_piece_color(sprite)
                    for solid_col in range(sprite.width):
                        if np.all(sprite.pixels[:, solid_col] != -1):
                            break
                    for solid_row in range(sprite.height):
                        if np.all(sprite.pixels[solid_row, :] != -1):
                            break
                    x_collides = sprite.x + solid_col >= wall_spr.x and sprite.x + solid_col < wall_spr.x + wall_spr.width
                    y_collides = sprite.y + solid_row >= wall_spr.y and sprite.y + solid_row < wall_spr.y + wall_spr.height
                    cy = sprite.height // 2
                    cx = sprite.width // 2


                    def _emit_cross_shift_log(direction: str) -> None:
                        cdx, cdy, cdw, cdh = self._to_display_bbox(sprite)
                        self.action_log.append(
                            f"[change]:[{sprite.name}]:[sname({sprite.name});shape(cross)_({direction});position({cdx}_{cdy});bbox({cdw}_{cdh})]:{sprite.name} hits the wall and the intersection shifts {direction}.|The Object hits the wall and the intersection shifts {direction}."
                        )
                        self.action_log_l2.append(
                            f"[change]:[{sprite.name}]:[sname({sprite.name});shape(cross)_({direction});position({cdx}_{cdy});bbox({cdw}_{cdh})]:{sprite.name}{direction}|Object{direction}"
                        )

                    if dx != 0:
                        shrink_dir = -3 if dx > 0 else 3
                        grow_dir = 3 if dx > 0 else -3
                        can_shrink_leading = solid_col > 0 if dx > 0 else solid_col < sprite.width - 2
                        can_grow_trailing = solid_col < sprite.width - 2 if dx > 0 else solid_col > 0



                        shrink_dir_label = "left"  if dx > 0 else "right"
                        grow_dir_label   = "right" if dx > 0 else "left"
                        if x_collides and y_collides:
                            sprite.move(-dx, -dy)
                        elif x_collides:
                            if can_shrink_leading:
                                sprite.pixels[:, solid_col] = -1
                                sprite.pixels[:, solid_col + shrink_dir] = piece_color
                                sprite.pixels[solid_row, solid_col] = piece_color
                                sprite.pixels[cy, cx] = CENTER_MARKER
                                _emit_cross_shift_log(shrink_dir_label)
                            else:
                                sprite.move(-dx, -dy)
                        elif y_collides:
                            sprite.move(-dx, -dy)
                            if can_grow_trailing:
                                sprite.pixels[:, solid_col] = -1
                                sprite.pixels[:, solid_col + grow_dir] = piece_color
                                sprite.pixels[solid_row, solid_col] = piece_color
                                sprite.pixels[cy, cx] = CENTER_MARKER
                                _emit_cross_shift_log(grow_dir_label)
                    elif dy != 0:
                        shrink_dir = -3 if dy > 0 else 3
                        grow_dir = 3 if dy > 0 else -3
                        can_shrink_leading = solid_row > 0 if dy > 0 else solid_row < sprite.height - 2
                        can_grow_trailing = solid_row < sprite.height - 2 if dy > 0 else solid_row > 0
                        shrink_dir_label = "up"   if dy > 0 else "down"
                        grow_dir_label   = "down" if dy > 0 else "up"
                        if y_collides and x_collides:
                            sprite.move(-dx, -dy)
                        elif y_collides:
                            if can_shrink_leading:
                                sprite.pixels[solid_row, :] = -1
                                sprite.pixels[solid_row + shrink_dir, :] = piece_color
                                sprite.pixels[solid_row, solid_col] = piece_color
                                sprite.pixels[cy, cx] = CENTER_MARKER
                                _emit_cross_shift_log(shrink_dir_label)
                            else:
                                sprite.move(-dx, -dy)
                        elif x_collides:
                            sprite.move(-dx, -dy)
                            if can_grow_trailing:
                                sprite.pixels[solid_row, :] = -1
                                sprite.pixels[solid_row + grow_dir, :] = piece_color
                                sprite.pixels[solid_row, solid_col] = piece_color
                                sprite.pixels[cy, cx] = CENTER_MARKER
                                _emit_cross_shift_log(grow_dir_label)
        piece_color = get_piece_color(sprite)
        cy = sprite.height // 2
        cx = sprite.width // 2
        if "hollow_piece" in sprite.tags:
            sprite.pixels[cy, cx] = -1
        elif "cross_piece" in sprite.tags:
            sprite.pixels[cy, cx] = piece_color
        else:
            for solid_col in range(sprite.width):
                if np.all(sprite.pixels[:, solid_col] != -1):
                    break
            for solid_row in range(sprite.height):
                if np.all(sprite.pixels[solid_row, :] != -1):
                    break
            if cy == solid_row or cx == solid_col:
                sprite.pixels[cy, cx] = piece_color
            else:
                sprite.pixels[cy, cx] = -1
        color_targets = self.current_level.get_sprites_by_tag("color_target")
        for target in color_targets:
            target_color = target.pixels[1, 1]
            if sprite.collides_with(target) and get_piece_color(sprite) != target_color:


                if target.name not in self.touched_color_targets:
                    self.touched_color_targets.add(target.name)
                target_w = target.width
                target_h = target.height

                self.active_from_color = int(piece_color)
                for i in range(sprite.height):
                    for j in range(sprite.width):
                        if sprite.x + j >= target.x and sprite.y + i >= target.y and (sprite.x + j < target.x + target_w) and (sprite.y + i < target.y + target_h):
                            if sprite.pixels[i, j] != -1:
                                sprite.pixels[i, j] = target_color
                self.active_target = target
                self.active_piece = sprite
                return target
        sprite.pixels[cy, cx] = CENTER_MARKER
        return None

    def _move_active_piece(self, dx: int, dy: int) -> Sprite | None:
        """"""
        pieces = self.current_level.get_sprites_by_tag("piece")
        active_pieces = [sprite for sprite in pieces if is_active_piece(sprite)]
        if active_pieces:
            return self._try_move_piece(active_pieces[0], dx, dy)
        return None

    def _to_display_xy(self, x: int, y: int) -> tuple[int, int]:
        """



        """
        cam = self.camera
        arc_scale = min(64 // cam.width, 64 // cam.height)
        x_off = (64 - cam.width  * arc_scale) // 2
        y_off = (64 - cam.height * arc_scale) // 2
        return (x - cam.x) * arc_scale + x_off, (y - cam.y) * arc_scale + y_off


    def _to_display_bbox(self, spr) -> tuple[int, int, int, int]:
        """

        """
        cam = self.camera
        arc_scale = min(64 // cam.width, 64 // cam.height)
        x_off = (64 - cam.width  * arc_scale) // 2
        y_off = (64 - cam.height * arc_scale) // 2
        dx = (spr.x - cam.x) * arc_scale + x_off
        dy = (spr.y - cam.y) * arc_scale + y_off
        dw = spr.width  * arc_scale
        dh = spr.height * arc_scale
        return dx, dy, dw, dh

    def _step_bar_pixel_len(self, steps: int) -> int:
        """
        """
        max_s = self.step_counter.max_steps
        if max_s <= 0:
            return 0
        return round(64 * steps / max_s)

    def _post_step(self, before_sprites: dict, before_steps: int) -> None:
        """




        """
        after_sprites = {id(spr): spr for spr in self.current_level.get_sprites()}


        for spr_id, spr in after_sprites.items():
            b = before_sprites.get(spr_id)
            if b is None or (not b["visible"] and spr.is_visible):
                dx, dy, dw, dh = self._to_display_bbox(spr)
                self.action_log.append(f"[appear]:[{spr.name}]:[sname({spr.name});position({dx}_{dy});bbox({dw}_{dh})]:{spr.name} appears at ({dx},{dy}).|Object appears at ({dx},{dy}).")
                self.action_log_l2.append(f"[appear]:[{spr.name}]:[sname({spr.name});position({dx}_{dy});bbox({dw}_{dh})]:{spr.name}({dx},{dy})|Object({dx},{dy})")



        _arc_scale_d = min(64 // self.camera.width, 64 // self.camera.height)
        for spr_id, b in before_sprites.items():
            spr = after_sprites.get(spr_id)
            gone = spr is None and b["visible"]
            hid  = spr is not None and b["visible"] and not spr.is_visible
            if gone or hid:
                bdx, bdy = self._to_display_xy(b["x"], b["y"])
                bdw = int(b.get("width", 0))  * _arc_scale_d
                bdh = int(b.get("height", 0)) * _arc_scale_d
                self.action_log.append(f"[disappear]:[{b['name']}]:[sname({b['name']});position({bdx}_{bdy});bbox({bdw}_{bdh})]:{b['name']} disappears from ({bdx},{bdy}).|Object disappears from ({bdx},{bdy}).")
                self.action_log_l2.append(f"[disappear]:[{b['name']}]:[sname({b['name']});position({bdx}_{bdy});bbox({bdw}_{bdh})]:{b['name']}({bdx},{bdy})|Object({bdx},{bdy})")


        for spr_id, spr in after_sprites.items():
            if not spr.is_visible:
                continue
            b = before_sprites.get(spr_id)
            if b is None or not b["visible"]:
                continue
            if (spr.x, spr.y) != (b["x"], b["y"]):
                bdx, bdy = self._to_display_xy(b["x"], b["y"])
                adx, ady, adw, adh = self._to_display_bbox(spr)
                self.action_log.append(f"[move]:[{spr.name}]:[sname({spr.name});position({bdx}_{bdy})_({adx}_{ady});bbox({adw}_{adh})]:{spr.name} moves from ({bdx},{bdy}) to ({adx},{ady}).|Object moves from ({bdx},{bdy}) to ({adx},{ady}).")
                self.action_log_l2.append(f"[move]:[{spr.name}]:[sname({spr.name});position({bdx}_{bdy})_({adx}_{ady});bbox({adw}_{adh})]:{spr.name}({bdx},{bdy})({adx},{ady})|Object({bdx},{bdy})({adx},{ady})")
            if spr.rotation != b["rotation"]:
                _rdx, _rdy, _rdw, _rdh = self._to_display_bbox(spr)
                self.action_log.append(f"[rotate]:[{spr.name}]:[sname({spr.name});position({_rdx}_{_rdy});bbox({_rdw}_{_rdh});angle({b['rotation']})_({spr.rotation})]:{spr.name} rotates from {b['rotation']}° to {spr.rotation}°.|Object rotates from {b['rotation']}° to {spr.rotation}°.")
                self.action_log_l2.append(f"[rotate]:[{spr.name}]:[sname({spr.name});position({_rdx}_{_rdy});bbox({_rdw}_{_rdh});angle({b['rotation']})_({spr.rotation})]:{spr.name}{b['rotation']}°{spr.rotation}°|Object{b['rotation']}°{spr.rotation}°")

        after_steps = self.step_counter.current_steps
        if after_steps != before_steps and self._step_bar_pixel_len(before_steps) != self._step_bar_pixel_len(after_steps):
            if after_steps < before_steps:
                self.action_log.append(f"[change]:[steps]:[sname(step_counter);count({before_steps})_({after_steps})]:The purple step bar at the bottom shrinks from the right ({before_steps}→{after_steps} steps remain).|The purple Object at the bottom shrinks from the right ({before_steps}→{after_steps}).")
                self.action_log_l2.append(f"[change]:[steps]:[sname(step_counter);count({before_steps})_({after_steps})]:{before_steps}→{after_steps}|Object{before_steps}→{after_steps}")
            else:
                self.action_log.append(f"[change]:[steps]:[sname(step_counter);count({before_steps})_({after_steps})]:The purple step bar at the bottom extends to the right ({before_steps}→{after_steps} steps).|The purple Object at the bottom extends to the right ({before_steps}→{after_steps}).")
                self.action_log_l2.append(f"[change]:[steps]:[sname(step_counter);count({before_steps})_({after_steps})]:{before_steps}→{after_steps}|Object{before_steps}→{after_steps}")


        if hasattr(self, "_frame_sprite_log"):
            self._frame_sprite_log.append(self.get_sprite_status())
        if hasattr(self, "_frame_nonsprite_log"):
            self._frame_nonsprite_log.append(self.get_nonsprite_status())
        self._log_state.snapshot_step()

    def step(self) -> None:
        """






        """

        self.action_log    = []
        self.action_log_l2 = []


        _before_sprites = {
            id(spr): {
                "name": spr.name,
                "x": spr.x, "y": spr.y,
                "width": spr.width, "height": spr.height,
                "rotation": spr.rotation,
                "visible": spr.is_visible,
            }
            for spr in self.current_level.get_sprites()
        }
        _before_steps = self.step_counter.current_steps


        if self.active_target and self.active_piece:

            target_color = self.active_target.pixels[1, 1]
            sprite = self.active_piece
            non_transparent_pixels = sprite.pixels[sprite.pixels != -1]
            if np.any(non_transparent_pixels != target_color):

                colored_coords = np.argwhere(sprite.pixels == target_color)
                for i, j in colored_coords.tolist():
                    for di in range(-1, 2):
                        for dj in range(-1, 2):
                            ni = i + di
                            nj = j + dj
                            if ni >= 0 and nj >= 0 and (ni < sprite.height) and (nj < sprite.width):
                                neighbor_val = sprite.pixels[ni, nj]
                                if neighbor_val != -1:
                                    sprite.pixels[ni, nj] = target_color
                color_name = COLOR_PALETTE.get(int(target_color), {}).get("name", str(int(target_color))).lower()


                from_idx = self.active_from_color if self.active_from_color is not None else int(target_color)
                old_color_name = COLOR_PALETTE.get(int(from_idx), {}).get("name", str(int(from_idx))).lower()
                sdx, sdy, sdw, sdh = self._to_display_bbox(sprite)




                self.action_log.append(f"[change]:[{sprite.name}]:[sname({sprite.name});color({old_color_name})_({color_name});position({sdx}_{sdy});bbox({sdw}_{sdh})]:The {color_name} region grows across {sprite.name}, replacing {old_color_name}.|The {color_name} region grows across the Object, replacing {old_color_name}.")
                self.action_log_l2.append(f"[change]:[{sprite.name}]:[sname({sprite.name});color({old_color_name})_({color_name});position({sdx}_{sdy});bbox({sdw}_{sdh})]:{sprite.name}{color_name}{old_color_name}|Object{color_name}{old_color_name}")

                if hasattr(self, "_frame_sprite_log"):
                    self._frame_sprite_log.append(self.get_sprite_status())
                if hasattr(self, "_frame_nonsprite_log"):
                    self._frame_nonsprite_log.append(self.get_nonsprite_status())
                self._log_state.snapshot_step()
                return

            cy = sprite.height // 2
            cx = sprite.width // 2
            sprite.pixels[cy, cx] = CENTER_MARKER
            self.active_target = None
            self.active_piece = None
            new_color_name = COLOR_PALETTE.get(int(target_color), {}).get("name", "").lower()

            from_idx = self.active_from_color if self.active_from_color is not None else int(target_color)
            old_color_name = COLOR_PALETTE.get(int(from_idx), {}).get("name", str(int(from_idx))).lower()

            self.active_from_color = None
            sdx, sdy, sdw, sdh = self._to_display_bbox(sprite)



            self.action_log.append(f"[change]:[{sprite.name}]:[sname({sprite.name});color({old_color_name})_({new_color_name});position({sdx}_{sdy});bbox({sdw}_{sdh})]:The {new_color_name} region grows across {sprite.name}, replacing {old_color_name}.|The {new_color_name} region grows across the Object, replacing {old_color_name}.")
            self.action_log_l2.append(f"[change]:[{sprite.name}]:[sname({sprite.name});color({old_color_name})_({new_color_name});position({sdx}_{sdy});bbox({sdw}_{sdh})]:{sprite.name}{new_color_name}{old_color_name}|Object{new_color_name}{old_color_name}")
        elif self.action.id == GameAction.ACTION1:

            self.step_counter.decrement()
            target = self._move_active_piece(0, -MOVE_STEP)
            if target:

                if hasattr(self, "_frame_sprite_log"):
                    self._frame_sprite_log.append(self.get_sprite_status())
                if hasattr(self, "_frame_nonsprite_log"):
                    self._frame_nonsprite_log.append(self.get_nonsprite_status())
                self._log_state.snapshot_step()
                return
        elif self.action.id == GameAction.ACTION2:

            self.step_counter.decrement()
            target = self._move_active_piece(0, MOVE_STEP)
            if target:
                if hasattr(self, "_frame_sprite_log"):
                    self._frame_sprite_log.append(self.get_sprite_status())
                if hasattr(self, "_frame_nonsprite_log"):
                    self._frame_nonsprite_log.append(self.get_nonsprite_status())
                self._log_state.snapshot_step()
                return
        elif self.action.id == GameAction.ACTION3:

            self.step_counter.decrement()
            target = self._move_active_piece(-MOVE_STEP, 0)
            if target:
                if hasattr(self, "_frame_sprite_log"):
                    self._frame_sprite_log.append(self.get_sprite_status())
                if hasattr(self, "_frame_nonsprite_log"):
                    self._frame_nonsprite_log.append(self.get_nonsprite_status())
                self._log_state.snapshot_step()
                return
        elif self.action.id == GameAction.ACTION4:

            self.step_counter.decrement()
            target = self._move_active_piece(MOVE_STEP, 0)
            if target:
                if hasattr(self, "_frame_sprite_log"):
                    self._frame_sprite_log.append(self.get_sprite_status())
                if hasattr(self, "_frame_nonsprite_log"):
                    self._frame_nonsprite_log.append(self.get_nonsprite_status())
                self._log_state.snapshot_step()
                return
        elif self.action.id == GameAction.ACTION5:




            self.step_counter.decrement()
            pieces = self.current_level.get_sprites_by_tag("piece")
            current_piece = [sprite for sprite in pieces if is_active_piece(sprite)][0]
            index = pieces.index(current_piece)
            next_piece = pieces[index + 1 if index < len(pieces) - 1 else 0]
            cur_dx, cur_dy, cur_dw, cur_dh = self._to_display_bbox(current_piece)
            nxt_dx, nxt_dy, nxt_dw, nxt_dh = self._to_display_bbox(next_piece)

            cam = self.camera
            arc_scale = min(64 // cam.width, 64 // cam.height)
            cur_cx_grid = current_piece.x + current_piece.width  // 2
            cur_cy_grid = current_piece.y + current_piece.height // 2
            nxt_cx_grid = next_piece.x    + next_piece.width    // 2
            nxt_cy_grid = next_piece.y    + next_piece.height   // 2
            cur_mdx, cur_mdy = self._to_display_xy(cur_cx_grid, cur_cy_grid)
            nxt_mdx, nxt_mdy = self._to_display_xy(nxt_cx_grid, nxt_cy_grid)
            self._deselect_all_pieces()
            i = next_piece.height // 2
            j = next_piece.width // 2
            next_piece.pixels[i, j] = CENTER_MARKER

            self.action_log.append(
                f"[disappear]:[center_marker]:[sname({current_piece.name});position({cur_mdx}_{cur_mdy});bbox({arc_scale}_{arc_scale})]:"
                f"The white center marker on {current_piece.name} at ({cur_mdx},{cur_mdy}) disappears."
                f"|The white center marker on the Object at ({cur_mdx},{cur_mdy}) disappears."
            )
            self.action_log_l2.append(
                f"[disappear]:[center_marker]:[sname({current_piece.name});position({cur_mdx}_{cur_mdy});bbox({arc_scale}_{arc_scale})]:"
                f"({cur_mdx},{cur_mdy}){current_piece.name}"
                f"|({cur_mdx},{cur_mdy})Object"
            )
            self.action_log.append(
                f"[appear]:[center_marker]:[sname({next_piece.name});position({nxt_mdx}_{nxt_mdy});bbox({arc_scale}_{arc_scale})]:"
                f"A white center marker appears on {next_piece.name} at ({nxt_mdx},{nxt_mdy}), indicating it is now selected."
                f"|A white center marker appears on the Object at ({nxt_mdx},{nxt_mdy})."
            )
            self.action_log_l2.append(
                f"[appear]:[center_marker]:[sname({next_piece.name});position({nxt_mdx}_{nxt_mdy});bbox({arc_scale}_{arc_scale})]:"
                f"({nxt_mdx},{nxt_mdy}){next_piece.name}"
                f"|({nxt_mdx},{nxt_mdy})Object"
            )

            self._set_event("selection_change", {
                "deselected": {
                    "name": current_piece.name,
                    "dx": cur_dx, "dy": cur_dy, "dw": cur_dw, "dh": cur_dh,
                },
                "selected": {
                    "name": next_piece.name,
                    "dx": nxt_dx, "dy": nxt_dy, "dw": nxt_dw, "dh": nxt_dh,
                },
            })


        if self._check_win():
            self._set_event("win", {
                "en": "[win]:[game]:[]:The level is cleared.|The level is cleared.",
                "l2": "[win]:[game]:[]:|",
            })
            self.next_level()
        elif not self.step_counter.current_steps:
            self._set_event("gameover", {
                "en": "[gameover]:[game]:[]:Step counter reached zero, game over.|The Object reached zero, game over.",
                "l2": "[gameover]:[game]:[]:0|Object0",
            })
            self.lose()


        self._post_step(_before_sprites, _before_steps)

        self.complete_action()

    def _set_event(self, key: str, value) -> None:
        """
        """
        self._log_state.set_event(key, value)

    def _compose_summary(
        self,
        agg_en: list[str],
        agg_l2: list[str],
        events: dict,
    ) -> tuple[list[str], list[str]]:
        """













        """
        import re as _re
        _RE_CHANGE_COLOR_GROW = _re.compile(
            r'^\[change\]:\[([^\]]+)\]:\[([^\]]*color\((\w+)\)_\((\w+)\)[^\]]*)\]:The \w+ region grows across .*$'
        )
        rewritten_en: list[str] = []
        rewritten_l2: list[str] = []
        for line_en, line_l2 in zip(agg_en, agg_l2):
            m = _RE_CHANGE_COLOR_GROW.match(line_en)
            if m:
                target, params, from_c, to_c = m.group(1), m.group(2), m.group(3), m.group(4)
                rewritten_en.append(
                    f"[change]:[{target}]:[{params}]:{target} changes color from {from_c} to {to_c}."
                    f"|The Object changes color from {from_c} to {to_c}."
                )
                rewritten_l2.append(
                    f"[change]:[{target}]:[{params}]:{target}{from_c}{to_c}"
                    f"|Object{from_c}{to_c}"
                )
            else:
                rewritten_en.append(line_en)
                rewritten_l2.append(line_l2)

        out_en, out_l2 = compose_default_summary(rewritten_en, rewritten_l2, events)

        sel = events.get("selection_change")
        if not sel:
            return out_en, out_l2


        kept_en: list[str] = []
        kept_l2: list[str] = []
        for line_en, line_l2 in zip(out_en, out_l2):
            if line_en.startswith("[appear]:[center_marker]:") or \
               line_en.startswith("[disappear]:[center_marker]:"):
                continue
            kept_en.append(line_en)
            kept_l2.append(line_l2)


        d = sel["deselected"]
        s = sel["selected"]
        kept_en.append(
            f"[bright]:[{d['name']}]:[sname({d['name']});position({d['dx']}_{d['dy']});"
            f"bbox({d['dw']}_{d['dh']});state(off)]:"
            f"{d['name']} is deselected and its white center marker turns off."
            f"|The Object's white center marker turns off."
        )
        kept_l2.append(
            f"[bright]:[{d['name']}]:[sname({d['name']});position({d['dx']}_{d['dy']});"
            f"bbox({d['dw']}_{d['dh']});state(off)]:"
            f"{d['name']}"
            f"|Object"
        )
        kept_en.append(
            f"[bright]:[{s['name']}]:[sname({s['name']});position({s['dx']}_{s['dy']});"
            f"bbox({s['dw']}_{s['dh']});state(selected)]:"
            f"{s['name']} becomes the active piece and shows the white center marker."
            f"|The Object's white center marker turns on."
        )
        kept_l2.append(
            f"[bright]:[{s['name']}]:[sname({s['name']});position({s['dx']}_{s['dy']});"
            f"bbox({s['dw']}_{s['dh']});state(selected)]:"
            f"{s['name']}"
            f"|Object"
        )
        return kept_en, kept_l2


