    def get_sprite_status(self) -> list[dict]:
        """






        """
        result = []
        for i, spr in enumerate(self.current_level.get_sprites()):
            tags = list(spr._tags) if spr._tags else []
            labels = [TAG_DISPLAY_NAMES.get(t, t) for t in tags]
            labels_l2 = [TAG_DISPLAY_NAMES_L2.get(t, t) for t in tags]
            result.append({
                "spr_id":   i,
                "name":     spr.name,
                "label":    ", ".join(labels) if labels else spr.name,
                "label_l2": ", ".join(labels_l2) if labels_l2 else spr.name,
                "tags":     tags,
                "x":        spr.x,
                "y":        spr.y,
                "width":    int(spr.width),
                "height":   int(spr.height),
                "rotation": spr.rotation,
            })
        return result

